package com.corecs.cpu.algorithm;
import com.corecs.cpu.model.*; import java.util.*;
public class RoundRobinAlgorithm implements SchedulingAlgorithm { public SimulationResult simulate(List<ProcessSpec> input,int quantum){if(quantum<1)throw new IllegalArgumentException("Time quantum must be at least 1");var ps=SchedulingSupport.sorted(input);var rem=new HashMap<String,Integer>();ps.forEach(p->rem.put(p.id(),p.burstTime()));var out=new ArrayList<GanttSegment>();Deque<ProcessSpec> q=new ArrayDeque<>();int t=0,i=0,done=0;while(done<ps.size()){while(i<ps.size()&&ps.get(i).arrivalTime()<=t)q.addLast(ps.get(i++));if(q.isEmpty()){int a=ps.get(i).arrivalTime();out.add(new GanttSegment("IDLE",t,a));t=a;continue;}var p=q.removeFirst();int run=Math.min(quantum,rem.get(p.id()));out.add(new GanttSegment(p.id(),t,t+run));t+=run;rem.put(p.id(),rem.get(p.id())-run);while(i<ps.size()&&ps.get(i).arrivalTime()<=t)q.addLast(ps.get(i++));if(rem.get(p.id())>0)q.addLast(p);else done++;}return SchedulingSupport.finish(ps,out);} }
